{"intent":"Fuzz with correct LRU/LRI reference model","command":"cd work/repo && python3 - <<'EOF'
import random
from collections import OrderedDict
from boltons.cacheutils import LRU, LRI

random.seed(1)

def make_model(cls, max_size):
    # OrderedDict proxies the linked list: front = least recent, end = most recent
    return OrderedDict()

def check(c, model, ctx):
    # keys+values must match the ll exactly
    if dict(c) != dict(model):
        print('DICT mismatch', ctx, dict(c), dict(model)); return False
    if set(c.keys()) != set(model.keys()):
        print('KEYSET mismatch', ctx, set(c.keys()), set(model.keys())); return False
    if len(c) != len(model) or len(c) > c.max_size:
        print('LEN mismatch', ctx, len(c), len(model), c.max_size); return False
    for k in c:
        if c[k] != model[k]:
            print('GETITEM mismatch', ctx, k, c[k], model[k]); return False
    return True

for cls in (LRU, LRI):
    for trial in range(300):
        max_size = random.randint(1, 5)
        c = cls(max_size=max_size)
        m = OrderedDict()
        for step in range(400):
            k = random.choice('abcdef')
            op = random.choice(['set','get','get','del','pop','setdefault','update','clear','copy','popitem'])
            ctx = (cls.__name__, trial, step, op, k)
            if op == 'set':
                v = random.randint(0, 99)
                c[k] = v
                if k in m: m.move_to_end(k)
                else:
                    if len(m) >= max_size: m.popitem(last=False)
                    m[k] = v
                if k in m: m[k] = v
            elif op == 'get':
                try: cv = c[k]
                except KeyError:
                    if k in m: print('miss on present key', ctx); raise SystemExit
                    cv = None
                else:
                    if k not in m: print('hit on absent key', ctx); raise SystemExit
                    if cv != m[k]: print('GET mismatch', ctx, cv, m[k]); raise SystemExit
                    if cls is LRU: m.move_to_end(k)
            elif op == 'del':
                if k in m:
                    del c[k]; del m[k]
                elif k in c:
                    print('ghost in dict', ctx); raise SystemExit
            elif op == 'pop':
                if k in m:
                    got, exp = c.pop(k, None), m.pop(k)
                    if got != exp: print('POP mismatch', ctx, got, exp); raise SystemExit
                else:
                    if c.pop(k, '<none>') != '<none>': print('POP ghost', ctx); raise SystemExit
            elif op == 'setdefault':
                d = random.randint(0, 99)
                got = c.setdefault(k, d)
                if k in m:
                    if got != m[k]: print('setdefault hit mismatch', ctx, got, m[k]); raise SystemExit
                    if cls is LRU: m.move_to_end(k)
                else:
                    if len(m) >= max_size: m.popitem(last=False)
                    m[k] = d
                    if got != d: print('setdefault miss mismatch', ctx, got, d); raise SystemExit
            elif op == 'update':
                d = {random.choice('abcdef'): random.randint(0, 99) for _ in range(3)}
                c.update(d)
                for kk, vv in d.items():
                    if kk in m: m.move_to_end(kk)
                    else:
                        if len(m) >= max_size: m.popitem(last=False)
                        m[kk] = vv
                    m[kk] = vv
            elif op == 'popitem':
                try: item = c.popitem()
                except KeyError:
                    if m: print('popitem KeyError w/ nonempty', ctx); raise SystemExit
                    m.clear()
                else:
                    if item[0] not in m: print('popitem popped ghost', ctx, item); raise SystemExit
                    exp = m.pop(item[0])
                    if item[1] != exp: print('popitem value mismatch', ctx, item, exp); raise SystemExit
            elif op == 'clear':
                c.clear(); m.clear()
            elif op == 'copy':
                cc = c.copy()
                if dict(cc) != dict(c): print('copy mismatch', ctx); raise SystemExit
            if not check(c, m, ctx): raise SystemExit
print('fuzz OK')
EOF"}

