import random
from boltons.cacheutils import LRU, LRI

random.seed(42)
for cls in (LRU, LRI):
    fails = 0
    for trial in range(200):
        max_size = random.randint(1, 5)
        c = cls(max_size=max_size)
        ref = {}      # model: key -> value
        recency = []  # model: ll order, front = most recent
        for step in range(60):
            op = random.choice(['set'] * 5 + ['get', 'del', 'pop', 'setdefault', 'update'])
            k = random.choice('abcde')
            if op == 'set':
                v = random.randint(0, 99)
                c[k] = v
                if k in ref:
                    recency.remove(k)
                else:
                    if len(ref) >= max_size:
                        ev = recency.pop(0)
                        del ref[ev]
                    ref[k] = v
                    recency.append(k)
                    continue  # ref[k] set below
                ref[k] = v
                recency.append(k)
            elif op == 'get':
                if k in ref:
                    assert c[k] == ref[k], (cls, trial, step, op, k, c[k], ref[k])
                    # get() moves to front for both LRI (via __getitem__? LRI __getitem__ doesn't move)
            elif op == 'del':
                if k in ref:
                    del c[k]; del ref[k]; recency.remove(k)
                else:
                    try:
                        del c[k]; raise AssertionError('should raise')
                    except KeyError: pass
            elif op == 'pop':
                got = c.pop(k, 'MISS')
                exp = ref.pop(k, 'MISS')
                if k in ref or exp != 'MISS':
                    pass
                if exp != 'MISS':
                    recency.remove(k) if k in recency else None
                assert got == exp, (cls, trial, step, op, k, got, exp)
            elif op == 'setdefault':
                d = random.randint(0, 99)
                got = c.setdefault(k, d)
                exp = ref[k] if k in ref else d
                if k not in ref:
                    # insert path like 'set'
                    if len(ref) >= max_size:
                        ev = recency.pop(0); del ref[ev]
                    ref[k] = d; recency.append(k)
                assert got == exp, (cls, trial, step, op, k, got, exp)
            elif op == 'update':
                pairs = {random.choice('abcde'): random.randint(0, 99) for _ in range(2)}
                c.update(pairs)
                for k2, v2 in pairs.items():
                    if k2 in ref:
                        ref[k2] = v2
                        recency.remove(k2); recency.append(k2)
                    else:
                        if len(ref) >= max_size:
                            ev = recency.pop(0); del ref[ev]
                        ref[k2] = v2; recency.append(k2)
            # invariant checks every step
            d = dict(c)
            link = {k2: c._link_lookup[k2][3] for k2 in c._link_lookup}
            if set(d) != set(ref):
                print('KEY MISMATCH', cls, trial, step, op, sorted(d), sorted(ref)); fails += 1; break
            if any(d[k2] != ref[k2] for k2 in ref):
                print('VAL MISMATCH', cls, trial, step, op, d, ref); fails += 1; break
            if set(d) != set(link) or any(d[k2] != link[k2] for k2 in d):
                print('LL MISMATCH', cls, trial, step, op, d, link); fails += 1; break
            if len(c) > max_size:
                print('SIZE', cls, trial, step, len(c), max_size); fails += 1; break
            if list(c.values()) != [d[k2] for k2 in d]:
                print('VALUES', cls); fails += 1; break
        if fails: break
    print(cls.__name__, 'model test failures:', fails)
