                        prerelease=f"{prerelease_token}{num + 1}", build=None
                    )

                if not (
                    version.prerelease == prerelease_token
                    or version.prerelease.startswith(prerelease_token + ".")
                ):
                    return version.replace(prerelease=f"{prerelease_token}.1", build=None)
