{"intent": "Map exact index/pop out-of-range behavior", "command": "cd work/repo && python3 - <<'PY'
from boltons.setutils import IndexedSet

def probe(lens):
    for n in lens:
        s = IndexedSet(range(n))
        # dense (no dead)
        pos_fail = []
        for i in range(-2*n, 2*n):
            try:
                s[i]
            except IndexError:
                pos_fail.append(i)
        expected_raise = set(range(-n, n))  # indices that should work
        # dense: raises everywhere outside [-n, n)
        ok = all((i in expected_raise) == (i in set(pos_fail)) for i in range(-2*n, 2*n))
        # now with removal
        if n >= 3:
            s.remove(1)
            m = n - 1
            fails = []
            for i in range(-2*n, 2*n):
                try:
                    s[i]
                except IndexError:
                    fails.append(i)
            should_raise = set(i for i in range(-2*m, 2*m) if not (-m <= i < m))
            should_work = set(range(-m, m))
            bad = [i for i in fails if i in should_work] + [i for i in range(-2*n,2*n) if i not in fails and i not in should_work]
            print(f"n={n} dense_ok={ok} after-remove len={len(s)} mismatches={sorted(bad)}")

probe([3, 5, 8, 10, 16, 20, 40])

# pop behavior
print("--- pop ---")
for n in (3, 5, 8, 10, 16, 20):
    for rem in [None, 1]:
        s = IndexedSet(range(n))
        if rem is not None and n > 2:
            s.remove(rem)
        m = len(s)
        bad = []
        for i in range(-2*m-2, 2*m+3):
            try:
                t = IndexedSet(s)
                v = t.pop(i)
                if not (-m <= i < m):
                    bad.append((i, v, "no-raise-out-of-range"))
                else:
                    exp = list(s)[i]
                    if v != exp:
                        bad.append((i, v, f"wrong value exp {exp}"))
            except IndexError:
                if -m <= i < m:
                    bad.append((i, "raised-but-should-work"))
            except Exception as e:
                bad.append((i, type(e).__name__))
        if bad:
            print(f"n={n} rem={rem} len={m} pop mismatches: {bad}")
print("pop probe done")
