    const { major: M, minor: m, patch: p } = c.semver
    vs.add(String(c.semver))
    vs.add(`${M}.${m}.${p}`)
    vs.add(`${M}.${m}.${p + 1}`)
    vs.add(`${M}.${m + 1}.0`)
    vs.add(`${M + 1}.0.0`)
