{"intent": "Compare old vs new value_chain behavior across edge cases", "command": "python3 - <<'EOF'
import itertools

def old_value_chain(*args):
    scalar_types = (str, bytes)
    for value in args:
        if isinstance(value, scalar_types):
            yield value
            continue
        try:
            yield from value
        except TypeError:
            yield value

def new_value_chain(*args):
    scalar_types = (str, bytes)
    for value in args:
        if isinstance(value, scalar_types):
            yield value
            continue
        try:
            iterator = iter(value)
        except TypeError:
            yield value
            continue
        yield from iterator

def run(fn, *args):
    try:
        out = []
        for x in fn(*args):
            out.append(repr(x))
        return 'ok:' + ','.join(out)
    except TypeError as e:
        return 'TypeError:' + str(e)

def gen_mid():
    yield 1
    yield 2
    raise TypeError('gen boom')

def gen_first():
    raise TypeError('first boom')
    yield

class IterRaises:
    def __iter__(self):
        raise TypeError('iter boom')

class IterReturnsNonIterator:
    def __iter__(self):
        return 42

class IterGivesBadNext:
    def __iter__(self):
        return self
    def __next__(self):
        raise TypeError('next boom')

class OldSeqAtZero:
    def __getitem__(self, i):
        raise TypeError('getitem zero')

class OldSeqMidway:
    def __getitem__(self, i):
        if i < 2:
            return i
        raise TypeError('getitem midway')

class SubIterRaisesMidway:
    def __iter__(self):
        return map(abs, [-1, 2, 'x'])

cases = [
    ('int', (3,)),
    ('none', (None,)),
    ('object', (object(),)),
    ('str', ('abc',)),
    ('bytes', (b'abc',)),
    ('bytearray', (bytearray(b'ab'),)),
    ('str-subclass', (type('S', (str,), {})('hi'),)),
    ('list', ([1,2],)),
    ('dict', ({'a': 1},)),
    ('map-mid', (map(abs, [-1, 2, 'x']),)),
    ('gen-mid', (gen_mid(),)),
    ('gen-first', (gen_first(),)),
    ('iter-raises', (IterRaises(),)),
