const path = require('path')
const pick = (p) => require(path.resolve(p))
const A = pick('work/orig')   // original
const B = pick('work/repo')   // fixed

const optsList = [
  {},
  { includePrerelease: true },
  { rtl: true },
  { rtl: true, includePrerelease: true },
  { loose: true, includePrerelease: true },
]

const describe = (v) => {
  if (!v) return 'null'
  return `${v.version}|pre=${JSON.stringify(v.prerelease)}|build=${JSON.stringify(v.build)}|raw=${v.raw}`
}

const same = (a, b) => {
  if (!a && !b) return true
  if (!a || !b) return false
  return describe(a) === describe(b)
}

// deterministic PRNG
let seed = 12345
const rnd = () => (seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648
const pickOne = (arr) => arr[Math.floor(rnd() * arr.length)]

const pieces = ['1', '2', '10', '0', '01', '17', 'rc', 'alpha', 'beta', 'nightly', 'a', 'f3', '7f3c', '9e1d',
  '4821', '.', '-', '+', ' ', '/', 'v', '=', 'x', 'X', 'build', 'meta', 'a-b', '1a', '2b', '0x', '_']

const gen = () => {
  const n = 1 + Math.floor(rnd() * 9)
  let s = ''
  for (let i = 0; i < n; i++) s += pickOne(pieces)
  return s
}

const ranges = ['1.2.3', '>=1.2.3-rc.1', '^1.2.3', '~1.2.3-a', '>=1.0.0 <2.0.0', '1.2.x', '*', '>=1.2.3-0']

const diffs = []
const N = 30000
for (let i = 0; i < N; i++) {
  const v = gen()
  for (const o of optsList) {
    const a = A.coerce(v, o)
    const b = B.coerce(v, o)
    if (!same(a, b)) diffs.push(['coerce', v, JSON.stringify(o), describe(a), describe(b)])
  }
  const pa = A.valid(v) , pb = B.valid(v)
  if (pa !== pb) diffs.push(['valid', v, '', String(pa), String(pb)])
  for (const r of ranges) {
    let sa, sb
    try { sa = A.satisfies(v, r) } catch (e) { sa = 'err:' + e.message }
    try { sb = B.satisfies(v, r) } catch (e) { sb = 'err:' + e.message }
    if (sa !== sb) diffs.push(['satisfies', v, r, String(sa), String(sb)])
  }
}
console.log('diffs:', diffs.length)
const kinds = {}
for (const d of diffs) kinds[d[0]] = (kinds[d[0]] || 0) + 1
console.log(kinds)
const shown = new Set()
for (const d of diffs) {
  const key = d[0] + '|' + d[1]
  if (shown.has(key)) continue
  shown.add(key)
  if (shown.size > 40) break
  console.log(JSON.stringify(d))
}
