from pathlib import Path
p = Path("src/semver/version.py")
s = p.read_text()
old = '''        def prerelease_key(identifier: str) -> tuple[int, int, str]:
            if not identifier.isdigit():
                return (1, 0, identifier)

            if not identifier.isascii():
                identifier = str(int(identifier))

            # Compare decimal values without converting arbitrarily long
            # ASCII identifiers to integers. Keep constructor leading zeros.
            normalized = identifier.lstrip("0") or "0"
            return (0, len(normalized), normalized)
'''
new = '''        def numeric_key(identifier: str) -> tuple[int, int, str]:
            # Compare decimal values without converting arbitrarily long
            # ASCII identifiers to integers. Keep constructor leading zeros.
            normalized = identifier.lstrip("0") or "0"
            return (0, len(normalized), normalized)

        def prerelease_key(identifier: str) -> tuple[int, int, str]:
            if identifier.isdigit():
                if not identifier.isascii():
                    identifier = str(int(identifier))
                return numeric_key(identifier)

            # Split an optional trailing number so that old-style tokens like
            # "rc9" and "rc10" keep their natural (numeric) order: the plain
            # text part is compared first, the number only breaks a tie.
            match = re.fullmatch(r"(.*?)(\\d+)", identifier)
            if match and match.group(1):
                text, number = match.groups()
                if not number.isascii():
                    number = str(int(number))
                return (2, 0, text, *numeric_key(number))

            # Non-numeric identifiers always sort after numeric ones.
            return (1, 0, identifier)
'''
