{"intent": "Find outputs exceeding precision in post-fix, split by pre-fix status", "command": "cd work/repo && python3 - <<'PY'
import sys, math, re, itertools, collections, types
sys.path.insert(0, "src")
src = open("src/humanize/number.py").read()
new_block = '''
    # Rounding can carry the scaled value over the next power of ten without
    # crossing into a new prefix (e.g. 9.996 rounds to 10.0). Formatting at
    # the current precision would then print one digit more than requested,
    # so drop one decimal place to keep the result at `precision` digits.
    if round(abs(value), digits) >= 10 ** (exponent % 3 + 1):
        digits = max(digits - 1, 0)
'''
pre_src = src.replace(new_block, "")
def make_metric(s):
    mod = types.ModuleType("m"); mod.__name__ = "humanize.number"
    exec(compile(s, "number.py", "exec"), mod.__dict__)
    return mod.metric
post, pre = make_metric(src), make_metric(pre_src)

def digits_report(s):
    if "x 10" in s: return None
    m = re.fullmatch(r"-?(\d+(?:\.\d+)?)\s*\S*", s)
    if not m: return None
    intp, _, frac = m.group(1).partition(".")
    if frac: return len(intp.lstrip("0")) + len(frac)
    if intp == "0": return 0
    return len(intp)

def run(f, v, p):
    try: return ("ok", f(v, precision=p))
    except Exception as e: return ("exc", repr(e))

mants = [1,1.5,9.9,9.94,9.95,9.994,9.995,9.996,9.9996,9.999999,10,10.4,99.4,99.5,99.94,99.95,99.996,99.9996,100,100.4,104,999.4,999.5,999.96,999.996,999.9996,0.9996,0.99996]
exps = list(range(-33,34)); precs=[0,1,2,3,4,5,6]

counts = collections.Counter(); ex = collections.defaultdict(list)
for mant,e,p,sign in itertools.product(mants,exps,precs,[1,-1]):
    v = sign*mant*10.0**e
    ka, a = run(post, v, p); kb, b = run(pre, v, p)
    if ka=="exc" or kb=="exc":
        key = "exc_both" if (ka=="exc" and kb=="exc") else ("exc_post_only_REGRESSION" if ka=="exc" else "exc_pre_only")
        counts[key]+=1
        if len(ex[key])<8: ex[key].append((v,p,a if ka=="exc" else None,b if kb=="exc" else None))
        continue
    if a==b: counts["same"]+=1
    na, nb = digits_report(a), digits_report(b)
    if na is not None and p>0 and na>p:
        key = "over_post_reg" if (nb is None or nb<=p) else "over_post_presuf"
        counts[key]+=1
        if len(ex[key])<15: ex[key].append((v,p,b,a,na,nb))
    else:
        counts["ok_post"]+=1

print(dict(counts))
for k in ex:
    print("\n##", k)
    for t in ex[k]: print("  ", t)
PY"}

{"intent": "Brute-force check for round() vs format() disagreement near carry thresholds", "command": "cd work/repo && python3 - <<'PY'
import math, random, struct
random.seed(0)

def int_digits_of_fmt(x, d):
    s = format(abs(x), f".{d}f")
    intp = s.split(".")[0]
    return len(intp)

mismatches = []
# cases: m in 0..2 => value in [10^m, 10^(m+1)); threshold T=10^(m+1)
for m in range(3):
    T = 10.0 ** (m + 1)
    lo, hi = 10.0 ** m, T
    cands = []
    # dense near the carry boundary: values that round up to T at digit d
    for d in range(0, 7):
        step = 10.0 ** (-d)
        base = T - step / 2  # exact tie at d decimals
        for k in range(-4, 5):
            c = base + k * step / 8
            if lo <= c < hi:
                cands.append((c, d))
        # neighbours with binary representation just around the tie
        for _ in range(200):
            c = random.uniform(max(lo, T - 8 * step), hi)
            cands.append((c, d))
    # also random overall
    for _ in range(4000):
        cands.append((random.uniform(lo, hi), random.randint(0, 6)))

    for x, d in cands:
        cond = round(abs(x), d) >= T
        prints_extra = int_digits_of_fmt(x, d) > m + 1
        if cond != prints_extra:
            mismatches.append((x, d, T, cond, prints_extra, format(x, f".{d}f")))

print("mismatch count:", len(mismatches))
for t in mismatches[:20]:
    print(t)
PY"}

