from pathlib import Path
p = Path("more_itertools/more.py")
s = p.read_text()
old = """    scalar_types = (str, bytes)
    for value in args:
        if isinstance(value, scalar_types):
            yield value
            continue
        try:
            yield from value
        except TypeError:
            yield value
