const SemVer = require('./classes/semver')
const semver = require('./')
function oldPre(version, identifier, identifierBase) {
  const s = new SemVer(version)
  const base = Number(identifierBase) ? 1 : 0
  if (s.prerelease.length === 0) { s.prerelease = [base] }
  else {
    let i = s.prerelease.length
    while (--i >= 0) { if (typeof s.prerelease[i] === 'number') { s.prerelease[i]++; i = -2 } }
    if (i === -1) {
      if (identifier === s.prerelease.join('.') && identifierBase === false) throw new Error('dup')
      s.prerelease.push(base)
    }
  }
  if (identifier) {
    let pre = [identifier, base]
    if (identifierBase === false) pre = [identifier]
    if (compareIdentifiers(s.prerelease[0], identifier) === 0) {
      if (isNaN(s.prerelease[1])) s.prerelease = pre
    } else { s.prerelease = pre }
  }
  return s.format()
}
const cases = [
  ['1.2.3-rc.next.3','rc.next',undefined],
  ['1.2.3-rc.next.3','rc.next',false],
  ['1.2.3-rc.next.0','rc.next',false],
  ['1.2.3-rc.next','rc.next',false],
  ['1.2.3-rc.next.beta','rc.next',undefined],
  ['1.2.3-rc.next.beta','rc.next',false],
  ['1.2.3-rc.next.next.3','rc.next',undefined],
  ['1.2.3-alpha.beta','alpha',undefined],
  ['1.2.3-alpha.beta','alpha.beta',undefined],
  ['1.2.3-beta.1','beta.1',undefined],
  ['1.2.3-beta.1','beta.1',false],
  ['1.2.3-beta.1.2','beta.1',undefined],
  ['1.2.3-beta.1.2','beta.1',false],
  ['1.2.3-rc.1.0','rc.1',undefined],
  ['1.2.3-rc.1.0','rc.1',false],
  ['1.2.3-alpha.1','alpha',undefined],
  ['1.2.3-alpha.1','alpha',false],
  ['1.2.3-alpha.1.2','alpha',undefined],
]
for (const [v,id,ib] of cases) {
  let oldR, newR
  try { oldR = oldPre(v,id,ib) } catch(e){ oldR='THROW:'+e.message }
  try { newR = semver.inc(v,'prerelease',undefined,id,ib) } catch(e){ newR='THROW:'+e.message }
  const mark = oldR===newR?'SAME':'DIFF'
  console.log(mark, JSON.stringify([v,id,ib]), 'old=',oldR,'new=',newR)
}
