const before =
  "      } else if (!c.operator && gt.operator === '>=' &&\n                 !satisfies(gt.semver, String(c), options)) {"
const after1 =
  "      } else if (gt.operator === '>=' &&\n                 !satisfies(gt.semver, String(c), options)) {"
if (!src.includes(before)) throw new Error('change1 pattern not found')
src = src.replace(before, after1)

const before2 =
  "      } else if (!c.operator && lt.operator === '<=' &&\n                 !satisfies(lt.semver, String(c), options)) {"
const after2 =
  "      } else if (lt.operator === '<=' &&\n                 !satisfies(lt.semver, String(c), options)) {"
if (!src.includes(before2)) throw new Error('change2 pattern not found')
src = src.replace(before2, after2)

const before3 = "    if (!satisfies(eq, domRange(dom), options)) {\n      return false\n    }"
const after3 = "    let domOk = true\n    for (const c of dom) {\n      if (!satisfies(eq, String(c), options)) {\n        domOk = false\n      }\n    }\n    if (!domOk) {\n      return false\n    }"
if (!src.includes(before3)) throw new Error('change3 pattern not found')
src = src.replace(before3, after3)

const m = new Module(path.resolve('./ranges/subset.orig.inmem.js'))
