}
const uniqV = [...new Set(versions.map(String))].map(s => new SemVer(s))

// ---- bounds pool ----
const bounds = ['0.0.0','1.0.0','1.2.3','2.0.0','2.3.4','6.2.9','6.3.0','6.3.1','6.4.0',
  '7.0.0','7.1.0','10.0.0','1.2.3-rc.4','1.2.3-rc.5','6.3.0-rc.4','6.3.0-rc.5','6.3.0-0',
  '6.4.0-0','6.4.0-rc.1','7.0.0-0','0.0.0-0','2.0.0-rc.1','1.9.9','6.9.9']
const ops = ['>=','>','<=','<','=','']

const pairs = new Set()
const add = (a,b) => { if (a && b && a!==b) pairs.add(a+'\u0000'+b) }
const rnd = arr => arr[Math.floor(Math.random()*arr.length)]

// targeted templates around the changed paths
for (const pre of ['6.3.0-rc.5','6.3.0-rc.4','6.4.0-rc.1','1.2.3-rc.5','7.0.0-0','6.4.0-0','1.2.3-0']) {
  for (const upper of ['7.0.0-0','6.4.0','7.0.0','6.3.1','1.2.4','2.0.0','6.4.0-0','10.0.0']) {
    add(`>=${pre} <${upper}`, `>=${pre} <7.0.0-0`)          // caret-prerelease style
    add(`>=${pre} <${upper}`, `^${pre}`)
    add(`^${pre}`, `>=${pre} <${upper}`)
    add(`>${pre} <=${upper}`, `>=${pre} <${upper}`)
    add(`>=${pre} <=${pre}`, `>=${pre} <${upper}`)           // point sub
    add(`>=${pre} <${upper}`, `<=${upper}`)
    add(`>=${pre} <${upper}`, `<${upper}`)
    add(`>=${pre}`, `<${upper}`)
    add(`<=${pre}`, `>=${bounds[3]} <7.0.0`)
    add(`<=${pre}`, `>${pre}`)
    add(`=${pre}`, `>=${pre} <${upper}`)
    add(`=${pre} >${bounds[3]}`, `>=6.0.0 <7.0.0`)           // eq + gt null path
    add(`=${pre} <${upper}`, `>=6.0.0 <7.0.0`)               // eq + lt null path
    add(`${pre}`, `>=${pre} <${upper}`)
    add(`>=${pre} <${upper}`, `${pre} || >=${upper} <8.0.0`)
  }
}
// random comparator-set pairs (1-3 comps) + caret/tilde/or/hyphen/star
const randRange = () => {
  const k = 1 + Math.floor(Math.random()*3)
  const cs = []
  for (let i=0;i<k;i++) cs.push(rnd(ops) + rnd(bounds))
  return cs.join(' ')
}
const randRange2 = () => {
  const r = Math.random()
  if (r < 0.25) return rnd(ops).replace('=','') + '^'... // placeholder (never reached)
}
for (let i=0;i<4000;i++) {
  let a = randRange(), b = randRange()
  const s = Math.random()
  if (s < 0.2) a = '^' + rnd(bounds)
  else if (s < 0.3) a = '~' + rnd(bounds)
  else if (s < 0.38) a = rnd(bounds) + ' - ' + rnd(bounds)
  else if (s < 0.44) a = '*'
  else if (s < 0.5) a = randRange() + ' || ' + randRange()
  const t = Math.random()
  if (t < 0.2) b = '^' + rnd(bounds)
  else if (t < 0.3) b = '~' + rnd(bounds)
  else if (t < 0.38) b = rnd(bounds) + ' - ' + rnd(bounds)
  else if (t < 0.44) b = '*'
  else if (t < 0.5) b = randRange() + ' || ' + randRange()
  add(a,b)
}

const parsed = []
for (const p of pairs) {
  const [a,b] = p.split('\u0000')
  try { parsed.push([a,b,new Range(a),new Range(b)]) } catch {}
}
console.log('pairs:', parsed.length, 'versions:', uniqV.length)

const check = (opts, label) => {
  const fps = [], fns = []
  for (const [a,b,ra,rb] of parsed) {
    let res
    try { res = subset(a,b,opts) } catch(e) { fps.push([a,b,'THROW '+e.message]); continue }
    const sat = v => ra.test(v) && !rb.test(v)
    if (res) {
      const w = uniqV.find(sat)
      if (w) fps.push([a,b,String(w)])
    } else {
      const w = uniqV.find(v => ra.test(v))
      if (!w) {
        // sub may be genuinely empty -> subset should be vacuously true
        fns.push([a,b,'EMPTY-SUB?'])
      } else if (!sat(w) === false) {}
      else fns.push([a,b,'witness:'+String(w)])
    }
  }
  console.log(label, 'FP:', fps.length, 'FN-candidates:', fns.length)
  fps.slice(0,15).forEach(x => console.log('  FP', JSON.stringify(x)))
  fns.slice(0,15).forEach(x => console.log('  FN?', JSON.stringify(x)))
  return [fps, fns]
}
check({}, 'default')
check({includePrerelease:true}, 'includePrerelease')
EOF"}

